package net.pearvoice.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.util.Base64;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> upload;private final ExecutorService pool=Executors.newFixedThreadPool(3);private final ConcurrentHashMap<String,HttpURLConnection> connections=new ConcurrentHashMap<>();private final Set<String> cancelled=Collections.newSetFromMap(new ConcurrentHashMap<String,Boolean>());private String saveId;private byte[] saveBytes;private static final String ORIGIN="https://appassets.androidplatform.net";
 public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Color.WHITE);web=new WebView(this);frame.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(frame);frame.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in;});frame.requestApplyInsets();web.setBackgroundColor(Color.WHITE);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);s.setTextZoom(100);web.addJavascriptInterface(new Bridge(),"PearAndroid");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(ORIGIN.equals(u.getScheme()+"://"+u.getHost()))return false;if("https".equals(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}}return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!"appassets.androidplatform.net".equals(u.getHost()))return null;String path=u.getPath();if(path==null||path.equals("/"))path="/index.html";if(path.contains("..")||!Arrays.asList("/index.html","/index.js","/native-bridge.js","/app.js","/style.css","/app.css","/icon.png").contains(path))return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));try{String mime=path.endsWith(".js")?"application/javascript":path.endsWith(".css")?"text/css":path.endsWith(".png")?"image/png":"text/html";Map<String,String> h=new HashMap<>();h.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; connect-src 'self' data: blob:; media-src 'self' blob: data:; frame-src 'none'; object-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,"UTF-8",200,"OK",h,getAssets().open("web"+path));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}});web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=callback;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pick.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(pick,41);}catch(Exception e){upload.onReceiveValue(null);upload=null;}return true;}});web.loadUrl(ORIGIN+"/index.html");}
 private void reply(String id,JSONObject data){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.__pearNativeResult&&window.__pearNativeResult("+JSONObject.quote(id)+","+data.toString()+")",null);});}
 private void fail(String id,String message){JSONObject o=new JSONObject();try{o.put("error",message);}catch(Exception ignored){}reply(id,o);}
 private boolean trusted(){return web!=null&&web.getUrl()!=null&&web.getUrl().startsWith(ORIGIN+"/");}
 public class Bridge {
  @JavascriptInterface public void cancel(String id){cancelled.add(id);HttpURLConnection c=connections.remove(id);if(c!=null)c.disconnect();}
  @JavascriptInterface public void request(String id,String json){runOnUiThread(()->{if(!trusted()){fail(id,"页面来源无效");return;}pool.execute(()->{HttpURLConnection c=null;try{JSONObject p=new JSONObject(json);URL url=new URL(p.getString("url"));if((!"https".equals(url.getProtocol())&&!"http".equals(url.getProtocol()))||url.getUserInfo()!=null)throw new IOException("接口必须使用 HTTP 或 HTTPS");String method=p.optString("method","GET");if(!method.equals("GET")&&!method.equals("POST"))throw new IOException("不支持的请求方式");if(cancelled.contains(id))throw new IOException("请求已取消");c=(HttpURLConnection)url.openConnection();connections.put(id,c);c.setInstanceFollowRedirects(false);c.setConnectTimeout(30000);c.setReadTimeout(180000);c.setRequestMethod(method);JSONObject h=p.optJSONObject("headers");if(h!=null)for(String k:Arrays.asList("Authorization","Content-Type","Accept"))if(h.has(k))c.setRequestProperty(k,h.getString(k));if(method.equals("POST")){byte[] data=p.optString("body","").getBytes("UTF-8");if(data.length>40*1024*1024)throw new IOException("请求内容超过 40 MB");c.setDoOutput(true);c.setFixedLengthStreamingMode(data.length);try(OutputStream out=c.getOutputStream()){out.write(data);}}int code=c.getResponseCode();InputStream stream=code>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream output=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){if(cancelled.contains(id))throw new IOException("请求已取消");if(output.size()+n>64*1024*1024)throw new IOException("响应超过 64 MB");output.write(buf,0,n);}}JSONObject result=new JSONObject();result.put("status",code);result.put("contentType",c.getContentType());result.put("body",Base64.encodeToString(output.toByteArray(),Base64.NO_WRAP));reply(id,result);}catch(Exception e){fail(id,e.getMessage()==null?"网络请求失败":e.getMessage());}finally{connections.remove(id);cancelled.remove(id);if(c!=null)c.disconnect();}});});}
  @JavascriptInterface public void save(String id,String json){try{JSONObject p=new JSONObject(json);byte[] bytes=Base64.decode(p.getString("data"),Base64.DEFAULT);if(bytes.length>200*1024*1024)throw new IOException("文件过大，请分批保存");runOnUiThread(()->{if(saveId!=null){fail(id,"请先完成上一个文件的保存");return;}if(!trusted()){fail(id,"页面来源无效");return;}saveId=id;saveBytes=bytes;Intent out=new Intent(Intent.ACTION_CREATE_DOCUMENT);out.addCategory(Intent.CATEGORY_OPENABLE);out.setType(p.optString("mime","application/octet-stream"));out.putExtra(Intent.EXTRA_TITLE,p.optString("name","梨梨配音室.png").replaceAll("[\\\\/:*?\"<>|]","_"));try{startActivityForResult(out,42);}catch(Exception e){saveId=null;saveBytes=null;fail(id,"无法打开文件保存窗口");}});}catch(Exception e){fail(id,"无法准备保存文件");}}
 }
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==41&&upload!=null){ArrayList<Uri> files=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)files.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)files.add(data.getData());}upload.onReceiveValue(files.isEmpty()?null:files.toArray(new Uri[0]));upload=null;}if(code==42&&saveId!=null){final String id=saveId;final byte[] bytes=saveBytes;saveId=null;saveBytes=null;if(result!=RESULT_OK||data==null||data.getData()==null){fail(id,"已取消保存");return;}final Uri uri=data.getData();pool.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();out.write(bytes);JSONObject done=new JSONObject();done.put("saved",true);reply(id,done);}catch(Exception e){fail(id,"保存失败，请重新选择位置");}});}}
 @Override public void onBackPressed(){web.evaluateJavascript("Boolean(window.PearVoice&&window.PearVoice.back())",value->{if(!"true".equals(value))new AlertDialog.Builder(this).setMessage("退出梨梨配音室？").setNegativeButton("继续听歌",null).setPositiveButton("退出",(d,w)->finish()).show();});}
 protected void onDestroy(){for(HttpURLConnection c:connections.values())c.disconnect();pool.shutdownNow();if(upload!=null)upload.onReceiveValue(null);if(web!=null){web.removeJavascriptInterface("PearAndroid");web.destroy();web=null;}super.onDestroy();}
}

